const valid = [];

for (const item of items) {
  const json = item.json || {};
  const url = (json.url || '').trim();

  if (!url || url.length < 10) continue;

  valid.push(item);
}

return valid.length > 0 ? valid : items;

const items = $input.all();
const parsed = [];

for (const item of items) {
  const xml = item.json.body || item.json.data || item.json || '';

  if (!xml || typeof xml !== 'string' || xml.length < 100 || xml.includes('Forbidden') || xml.includes('<html') || xml.includes('Cloudflare') || xml.includes('Human Verification') || xml.includes('CAPTCHA') || xml.includes('captcha') || xml.includes('AwsWaf') || xml.includes('405')) {
    continue;
  }

  if (xml.includes('<html') || xml.includes('<!DOCTYPE html') || xml.includes('Forbidden')) {
    continue;
  }

  const isAtom = xml.includes('<feed') && xml.includes('<entry');

  if (isAtom) {
    const entryRegex = /<entry[^>]*>([\s\S]*?)<\/entry>/gi;
    let entryMatch;
    let count = 0;

    while ((entryMatch = entryRegex.exec(xml)) !== null && count < 3) {
      const entryXml = entryMatch[1];
      const titleMatch = entryXml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
      const linkMatch = entryXml.match(/<link[^>]+href="([^"]+)"/i);

      const title = titleMatch ? titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/s, '$1').trim() : '';
      const link = linkMatch ? linkMatch[1].trim() : '';

      if (title && link) {
        parsed.push({
          json: {
            title: title,
            link: link,
            content: title,
            description: title,
            guid: link,
            contentSnippet: title.substring(0, 300)
          }
        });
        count++;
      }
    }
  } else {
    const channelMatch = xml.match(/<channel[^>]*>([\s\S]*?)<\/channel>/i);
    const channelContent = channelMatch ? channelMatch[1] : xml;

    const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
    let itemMatch;
    let count = 0;

    while ((itemMatch = itemRegex.exec(channelContent)) !== null && count < 3) {
      const itemXml = itemMatch[1];
      const titleMatch = itemXml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
      const linkMatch = itemXml.match(/<link[^>]*>([\s\S]*?)<\/link>/i);

      const title = titleMatch ? titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/s, '$1').trim() : '';
      const link = linkMatch ? linkMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/s, '$1').trim() : '';

      if (title || link) {
        parsed.push({
          json: {
            title: title || 'Sem título',
            link: link || '',
            content: title || '',
            description: title || '',
            guid: link || '',
            contentSnippet: (title || '').substring(0, 300)
          }
        });
        count++;
      }
    }
  }
}

console.log('Parse RSS - parsed items:', parsed.length);
return parsed.length > 0 ? parsed : [];

const item = $input.item.json;
const link = (item.link || item.guid || item.id || item.url || '').trim();
const title = (item.title || '').trim();
const summary = (item.contentSnippet || item.content || item.summary || item.description || '').replace(/<[^>]*>/g, '').trim();

if (!title && !summary && !link) {
  return [];
}

const finalTitle = title || link || 'Artigo recomendado';
const finalSummary = summary || finalTitle || 'Clique no link para ver o conteúdo completo.';
const cleanSummary = finalSummary.length > 300 ? finalSummary.substring(0, 300) + '...' : finalSummary;

const userContent = `Notícia/Artigo enviado: ${finalTitle}\nLink: ${link}\nResumo/Abstract: ${cleanSummary}`;

return [{
  json: {
    title: finalTitle,
    link: link,
    userContent: userContent
  }
}];

const systemPrompt = `Você é um engenheiro de software sênior com sólida experiência em arquitetura backend, Linux, contêineres e infraestrutura computacional. Sua missão é ler o resumo de uma notícia ou o abstract de um artigo científico de computação e criar uma thread técnica e fluida no Twitter (X) com exatamente 3 tweets, adotando uma postura analítica de quem compreende o impacto real daquela tecnologia ou paper no ecossistema de produção.

Diretrizes de Conteúdo e Estilo:
- Escreva de forma orgânica e natural, simulando o fluxo de pensamento de um desenvolvedor experiente compartilhando conhecimento. Evite estruturas mecânicas ou repetitivas entre os tweets.
- O primeiro tweet introduz o fato, problema técnico ou tese do paper com base no resumo fornecido. O segundo tweet aprofunda as implicações de engenharia e trade-offs por trás do fato. O terceiro amarra com o impacto de longo prazo, boas práticas de infraestrutura ou arquitetura backend.
- Mantenha o jargão técnico realista do mercado (deploy, throughput, runtime, tradeoff, pipeline), mas rejeite clichês corporativos como 'essencial', 'fundamental', 'revolucionar', 'impulsionar'.
- NUNCA termine posts com perguntas retóricas para gerar engajamento artificial.

Regras de Estrutura:
- A thread DEVE conter exatamente 3 posições no array de tweets.
- Cada tweet deve ser denso e ocupar bem o espaço disponível (entre 200 e 260 caracteres), terminando obrigatoriamente com a marcação correspondente: (1/3), (2/3) e (3/3).
- Retorne exclusivamente um JSON válido com as chaves: 'title', 'link' e 'tweets' (um array contendo as 3 strings dos tweets).
- Não coloque o link de referência dentro do array de tweets.
- Se o conteúdo for mínimo, crie tweets informativos baseados no título e link disponíveis.`;

const payload = {
  model: 'sensenova-6.8-flash-lite',
  messages: [
    {
      role: 'system',
      content: systemPrompt
    },
    {
      role: 'user',
      content: 'Notícia/Artigo a processar:\n' + $json.userContent + '\n\nLink: ' + ($json.link || 'Não fornecido')
    }
  ],
  temperature: 0.75,
  max_tokens: 2048
};

return [{ json: payload }];

const allInputs = $input.all();
let raw = '';

if (allInputs.length > 0) {
  const item = allInputs[0].json;

  if (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) {
    raw = item.choices[0].message.content;
  } else if (item.candidates && item.candidates[0] && item.candidates[0].content && item.candidates[0].content.parts && item.candidates[0].content.parts[0]) {
    raw = item.candidates[0].content.parts[0].text;
  } else if (item.content) {
    raw = item.content;
  } else if (typeof item === 'string') {
    raw = item;
  } else {
    raw = JSON.stringify(item);
  }
}

let cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let firstBrace = cleaned.indexOf('{');
let lastBrace = cleaned.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let content = {};
try {
  content = JSON.parse(cleaned);
} catch (e) {
  content = {
    title: cleaned.substring(0, 80).replace(/[\n\r]/g, ' ').trim() || 'Thread gerada',
    tweets: [cleaned.substring(0, 260)],
    link: ''
  };
}

let list = Array.isArray(content.tweets) ? content.tweets : [cleaned.substring(0, 260)];

return [{
  json: {
    title: content.title || 'Thread gerada',
    tweets: list,
    link: content.link || '',
    thread_preview: list.length > 0 ? list.join('\n\n---\n\n') : cleaned.substring(0, 260)
  }
}];

